# Import SQLAlchemy column descriptors and scalar types used to map Python attributes to PostgreSQL columns.
from sqlalchemy import Boolean, CheckConstraint, Column, DateTime, Index, Integer, String
# Import SQL functions so timestamps are generated by the database clock rather than application hosts.
from sqlalchemy.sql import func
# Import the shared declarative base so this model participates in application metadata and migrations.
from src.core.db import Base
from src.domain.lifecycle import StudentStatus

# Define the ORM entity representing one student moving through the provisioning pipeline.
class Student(Base):
    # Map this Python class to the PostgreSQL students table.
    __tablename__ = "students"
    __table_args__ = (
        CheckConstraint("health_score IS NULL OR health_score BETWEEN 0 AND 100", name="ck_students_health_score"),
        CheckConstraint("follow_up_count >= 0", name="ck_students_follow_up_count"),
        CheckConstraint(
            "status IN ('pending', 'queued', 'processing', 'onboarding_started', "
            "'completed', 'at_risk', 'offboarding', 'refunded', 'cancelled', "
            "'failed', 'manual_hold', 'scheduled')",
            name="ck_students_status",
        ),
        Index("ix_students_status_updated_at", "status", "updated_at"),
        Index("ix_students_csm_status", "assigned_csm_id", "status"),
        Index("ix_students_program_cohort_status", "program_type", "cohort", "status"),
        Index("ux_students_clickup_task_id", "clickup_task_id", unique=True),
    )

    # Store the database-generated internal identifier used for joins and queue messages.
    id = Column(Integer, primary_key=True, index=True)
    # Store the required human-readable name shown to operators and external systems.
    name = Column(String, nullable=False)
    # Enforce idempotency by allowing only one row for each GoHighLevel contact.
    ghl_contact_id = Column(String, unique=True, nullable=False)
    # Persist the optional readiness score used by operational prioritization.
    health_score = Column(Integer, default=100)
    # Track the workflow state shared by webhooks, workers, and reconciliation jobs.
    status = Column(String, default=StudentStatus.PENDING.value, nullable=False)
    # Retain the external ClickUp list identifier for reconciliation and support.
    clickup_list_id = Column(String, nullable=True)
    # Retain the external ClickUp task identifier so provisioning can be retried safely.
    clickup_task_id = Column(String, nullable=True)
    # Store the program tier that determines SLA thresholds and service behavior.
    program_type = Column(String, default="Standard", nullable=False)
    # Store the cohort used to segment dashboards, SLA policy, and operational reporting.
    cohort = Column(String, default="Default", nullable=False)
    # Record the CSM responsible for the student's follow-up work.
    assigned_csm_id = Column(String, nullable=True)
    # Record the latest meaningful interaction used to calculate follow-up lateness.
    last_interaction_at = Column(DateTime, server_default=func.now(), nullable=True)
    # Record when the current state began so status SLA time can be measured.
    sla_status_start_at = Column(DateTime, server_default=func.now(), nullable=True)
    # Count human follow-ups for auditability and operational reporting.
    follow_up_count = Column(Integer, default=0, nullable=False)
    # Allow operators to pause automation without deleting or changing the record.
    is_paused = Column(Boolean, default=False, nullable=False)
    # Let PostgreSQL timestamp record creation consistently across application instances.
    created_at = Column(DateTime, server_default=func.now())
    # Let SQLAlchemy ask PostgreSQL for a modification timestamp on updates.
    updated_at = Column(DateTime, onupdate=func.now(), server_default=func.now())
